    # Founder cost dashboard (plan §2): daily token spend per feature, surfaced in /admin.
    op.execute("""
        CREATE MATERIALIZED VIEW llm_cost_daily_by_feature AS
        SELECT
            date_trunc('day', created_at)::date AS day,
            feature,
            provider,
            model,
            count(*)            AS calls,
            sum(input_tokens)   AS input_tokens,
            sum(output_tokens)  AS output_tokens,
            sum(cost_usd)       AS cost_usd
        FROM llm_usage_events
        GROUP BY 1, 2, 3, 4
        WITH NO DATA
    """)
